(function($){$(document).ready(function(){$(".rh_multiselect").each(function(){var controls=$(this).find("div.rh_multiselect-controls");var list=$(this).find("ul.rh_multiselect-ul");var menu=$(this).find("div.rh_multiselect-menu-block").html();var maxheight=list.css("max-height");list.find("li").each(function(){var $li=$(this);var $div=$li.find("div.rh_multiselect-item:first");$li.prepend('<span class="pull-left icon-"></span>');$div.after('<div class="clearfix"></div>');if($li.find("ul.rh_multiselect-sub").length){$li.find("span.icon-").addClass("rh_multiselect-toggle icon-minus");
$div.find("label:first").after(menu);if(!$li.find("ul.rh_multiselect-sub ul.rh_multiselect-sub").length)$li.find("div.rh_multiselect-menu-expand").remove()}});list.find("span.rh_multiselect-toggle").click(function(){var $icon=$(this);if($icon.parent().find("ul.rh_multiselect-sub").is(":visible")){$icon.removeClass("icon-minus").addClass("icon-plus");$icon.parent().find("ul.rh_multiselect-sub").hide();$icon.parent().find("ul.rh_multiselect-sub span.rh_multiselect-toggle").removeClass("icon-minus").addClass("icon-plus")}else{$icon.removeClass("icon-plus").addClass("icon-minus");
$icon.parent().find("ul.rh_multiselect-sub").show();$icon.parent().find("ul.rh_multiselect-sub span.rh_multiselect-toggle").removeClass("icon-plus").addClass("icon-minus")}});controls.find("input.rh_multiselect-filter").keyup(function(){var $text=$(this).val().toLowerCase();list.find("li").each(function(){var $li=$(this);if($li.text().toLowerCase().indexOf($text)==-1)$li.hide();else $li.show()})});controls.find("a.rh_multiselect-checkall").click(function(){list.find("input").prop("checked",true)});
controls.find("a.rh_multiselect-uncheckall").click(function(){list.find("input").prop("checked",false)});controls.find("a.rh_multiselect-toggleall").click(function(){list.find("input").each(function(){var $input=$(this);if($input.prop("checked"))$input.prop("checked",false);else $input.prop("checked",true)})});controls.find("a.rh_multiselect-expandall").click(function(){list.find("ul.rh_multiselect-sub").show();list.find("span.rh_multiselect-toggle").removeClass("icon-plus").addClass("icon-minus")});
controls.find("a.rh_multiselect-collapseall").click(function(){list.find("ul.rh_multiselect-sub").hide();list.find("span.rh_multiselect-toggle").removeClass("icon-minus").addClass("icon-plus")});controls.find("a.rh_multiselect-showall").click(function(){list.find("li").show()});controls.find("a.rh_multiselect-showselected").click(function(){list.find("li").each(function(){var $li=$(this);var $hide=true;$li.find("input").each(function(){if($(this).prop("checked")){$hide=false;return false}});if($hide){$li.hide();
return}$li.show()})});controls.find("a.rh_multiselect-maximize").click(function(){list.css("max-height","");controls.find("a.rh_multiselect-maximize").hide();controls.find("a.rh_multiselect-minimize").show()});controls.find("a.rh_multiselect-minimize").click(function(){list.css("max-height",maxheight);controls.find("a.rh_multiselect-minimize").hide();controls.find("a.rh_multiselect-maximize").show()})});$("div.rh_multiselect a.checkall").click(function(){$(this).parent().parent().parent().parent().parent().parent().find("ul.rh_multiselect-sub input").prop("checked",
true)});$("div.rh_multiselect a.uncheckall").click(function(){$(this).parent().parent().parent().parent().parent().parent().find("ul.rh_multiselect-sub input").prop("checked",false)});$("div.rh_multiselect a.expandall").click(function(){var $parent=$(this).parent().parent().parent().parent().parent().parent().parent();$parent.find("ul.rh_multiselect-sub").show();$parent.find("ul.rh_multiselect-sub span.rh_multiselect-toggle").removeClass("icon-plus").addClass("icon-minus")});$("div.rh_multiselect a.collapseall").click(function(){var $parent=
$(this).parent().parent().parent().parent().parent().parent().parent();$parent.find("li ul.rh_multiselect-sub").hide();$parent.find("li span.rh_multiselect-toggle").removeClass("icon-minus").addClass("icon-plus")});$("div.rh_multiselect-item.hidechildren").click(function(){var $parent=$(this).parent();$(this).find("input").each(function(){var $sub=$parent.find("ul.rh_multiselect-sub").first();var $input=$(this);if($input.prop("checked")){$parent.find("span.rh_multiselect-toggle, div.rh_multiselect-menu").css("visibility",
"hidden");if(!$sub.parent().hasClass("hidelist"))$sub.wrap('<div style="display:none;" class="hidelist"></div>')}else{$parent.find("span.rh_multiselect-toggle, div.rh_multiselect-menu").css("visibility","visible");if($sub.parent().hasClass("hidelist"))$sub.unwrap()}})})})})(jQuery);
